import React, { useRef, useState } from "react";

const ProjectFilterScroller = ({
  filters,
  activeFilter,
  handleFilterClick,
  isAnimating,
}) => {
  const scrollContainerRef = useRef(null);

  const [hoveredFilter, setHoveredFilter] = useState(null);
  const [tooltipPos, setTooltipPos] = useState({ x: 0, y: 0 });

  const iconMap = {
    All: `${process.env.PUBLIC_URL}/assets/icons/all-icon.svg`,
    Python: `${process.env.PUBLIC_URL}/assets/icons/python-icon.svg`,
    SQL: `${process.env.PUBLIC_URL}/assets/icons/sql-icon.svg`,
    "Power BI": `${process.env.PUBLIC_URL}/assets/icons/power-bi-icon.svg`,
    "Google Looker Studio": `${process.env.PUBLIC_URL}/assets/icons/looker-studio-icon.svg`,
    JavaScript: `${process.env.PUBLIC_URL}/assets/icons/js-icon.svg`,
    Flutter: `${process.env.PUBLIC_URL}/assets/icons/flutter-icon.svg`,
    AWS: `${process.env.PUBLIC_URL}/assets/icons/aws-icon.svg`,
  };

  const handleWheel = (e) => {
    if (scrollContainerRef.current) {
      e.preventDefault();
      scrollContainerRef.current.scrollLeft += e.deltaY;
    }
  };

  const handleMouseEnter = (filter) => (e) => {
    const rect = e.currentTarget.getBoundingClientRect();
    setHoveredFilter(filter);
    setTooltipPos({
      x: rect.left + rect.width / 2,
      y: rect.top - 10,
    });
  };

  const handleMouseLeave = () => {
    setHoveredFilter(null);
  };

  return (
    <>
      {/* Filter Buttons */}
      <div className="relative z-10">
        <div
          className="flex overflow-x-auto overflow-visible py-4"
          ref={scrollContainerRef}
          onWheel={handleWheel}
          style={{ scrollbarWidth: "none", msOverflowStyle: "none" }}
        >
          <div className="flex space-x-4">
            {filters.map((filter) => (
              <button
                key={filter}
                onClick={() => handleFilterClick(filter)}
                disabled={isAnimating}
                onMouseEnter={handleMouseEnter(filter)}
                onMouseLeave={handleMouseLeave}
                className={`relative w-14 h-14 rounded-full transition-all duration-300 flex-shrink-0 ${
                  activeFilter === filter
                    ? "bg-gray-400 text-black scale-110 shadow-md"
                    : "bg-white hover:bg-gray-400 hover:scale-105"
                }`}
                style={{ overflow: "visible" }}
              >
                <img
                  src={iconMap[filter]}
                  alt={filter}
                  className="w-6 h-6 m-auto pointer-events-none"
                  draggable={false}
                />
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Tooltip muncul di luar, mengikuti posisi mouse */}
      {hoveredFilter && (
        <div
          className="fixed z-50 px-2 py-1 bg-black text-white text-sm rounded pointer-events-none transition-opacity duration-200"
          style={{
            top: tooltipPos.y,
            left: tooltipPos.x,
            transform: "translate(-50%, -100%)",
          }}
        >
          {hoveredFilter}
        </div>
      )}
    </>
  );
};

export default ProjectFilterScroller;
