import React, { useState, useEffect, useCallback, useMemo } from "react";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import ProjectCard from "./ProjectCard";
import ProjectDetailModal from "./ProjectDetailSection";
import ProjectFilterScroller from "./ProjectFilterScroller";
import projectsData from "../data/projects.json";

const ProjectSection = () => {
  // State for managing projects and animations
  const [activeFilter, setActiveFilter] = useState("All");
  const [projectsToDisplay, setProjectsToDisplay] = useState([]);
  const [visibleProjects, setVisibleProjects] = useState({});
  const [showMoreProjects, setShowMoreProjects] = useState(false);
  const [isAnimating, setIsAnimating] = useState(false);
  const [selectedProject, setSelectedProject] = useState(null);

  // Cache to store already loaded projects by filter
  const [projectsCache, setProjectsCache] = useState({
    All: { projects: [], loaded: false },
  });

  // Filter projects based on active filter
  const getFilteredProjects = useCallback(() => {
    if (activeFilter === "All") {
      return projectsData;
    }
    return projectsData.filter(
      (project) => project.tags && project.tags.includes(activeFilter)
    );
  }, [activeFilter]);

  // Handle filter changes with caching
  const handleFilterClick = useCallback(
    (filter) => {
      if (filter === activeFilter) return;

      setIsAnimating(true);

      // Start fade out animation
      const updatedVisibility = {};
      Object.keys(visibleProjects).forEach((id) => {
        updatedVisibility[id] = false;
      });
      setVisibleProjects(updatedVisibility);

      // Wait for fade out animation to complete
      setTimeout(() => {
        setActiveFilter(filter);
        // Filter will be updated in the next useEffect
      }, 300);
    },
    [activeFilter, visibleProjects]
  );

  // Update displayed projects when filter changes - now with caching
  useEffect(() => {
    // Check if we already have this filter in cache
    if (projectsCache[activeFilter] && projectsCache[activeFilter].loaded) {
      const cachedProjects = projectsCache[activeFilter].projects;
      const projectsToShow = showMoreProjects
        ? cachedProjects
        : cachedProjects.slice(0, 6);

      setProjectsToDisplay(projectsToShow);

      // Prepare fade in animation for cached projects
      const newVisibility = {};
      projectsToShow.forEach((project) => {
        newVisibility[project.id] = false;
      });

      setVisibleProjects(newVisibility);

      // Start fade-in animation
      setTimeout(() => {
        const updatedVisibility = {};
        projectsToShow.forEach((project) => {
          updatedVisibility[project.id] = true;
        });
        setVisibleProjects(updatedVisibility);
        setIsAnimating(false);

        // Refresh ScrollTrigger after projects are loaded
        if (ScrollTrigger) {
          ScrollTrigger.refresh();
        }
      }, 50);
    } else {
      // If not cached, fetch and cache the projects
      const filtered = getFilteredProjects();
      const projectsToShow = showMoreProjects ? filtered : filtered.slice(0, 6);

      // Update cache with new filter results
      setProjectsCache((prevCache) => ({
        ...prevCache,
        [activeFilter]: { projects: filtered, loaded: true },
      }));

      setProjectsToDisplay(projectsToShow);

      // Prepare fade in animation for new projects
      const newVisibility = {};
      projectsToShow.forEach((project) => {
        newVisibility[project.id] = false;
      });

      setVisibleProjects(newVisibility);

      // Delay to ensure DOM is updated before starting fade in
      setTimeout(() => {
        const updatedVisibility = {};
        projectsToShow.forEach((project) => {
          updatedVisibility[project.id] = true;
        });
        setVisibleProjects(updatedVisibility);
        setIsAnimating(false);

        // Refresh ScrollTrigger after projects are loaded
        if (ScrollTrigger) {
          ScrollTrigger.refresh();
        }
      }, 50);
    }
  }, [activeFilter, showMoreProjects, getFilteredProjects, projectsCache]);

  // Available filter options
  const filterOptions = useMemo(
    () => [
      "All",
      "Python",
      "SQL",
      "Power BI",
      "Google Looker Studio",
      "AWS",
      "JavaScript",
      "Flutter",
    ],
    []
  );

  return (
    <section className="py-8" id="project">
      <h2 className="text-3xl font-bold mb-8">My Project</h2>

      {/* Filter scroller component */}
      <ProjectFilterScroller
        filters={filterOptions}
        activeFilter={activeFilter}
        handleFilterClick={handleFilterClick}
        isAnimating={isAnimating}
      />

      {/* Project Grid with animation and empty state handling */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 min-h-[400px] mt-4">
        {isAnimating ? (
          // Show loading spinner during animation
          <div className="col-span-1 md:col-span-2 lg:col-span-3 flex justify-center items-center py-12">
            <div className="animate-spin rounded-full h-10 w-10 border-t-2 border-b-2 border-blue-500"></div>
          </div>
        ) : projectsToDisplay.length > 0 ? (
          // Show projects if available
          projectsToDisplay.map((project) =>
            project?.title && project?.image && project?.description ? (
              <div key={project.id} className="project-card-container">
                <ProjectCard
                  project={project}
                  isVisible={visibleProjects[project.id] ?? false}
                  onClick={(project) => setSelectedProject(project)}
                />
              </div>
            ) : null
          )
        ) : (
          // Show message if no projects match the filter
          <div className="col-span-1 md:col-span-2 lg:col-span-3 text-center py-12 text-gray-400">
            No filter-matched projects "{activeFilter}"
          </div>
        )}
      </div>

      {/* Add Show More/Less button if projects exceed 6 */}
      {!isAnimating && getFilteredProjects().length > 6 && (
        <div className="flex justify-center mt-8">
          <button
            onClick={() => setShowMoreProjects(!showMoreProjects)}
            className="flex items-center gap-2 px-6 py-3 bg-gray-800 text-gray-300 rounded-full hover:bg-gray-700 transition-colors"
            disabled={isAnimating}
          >
            {showMoreProjects ? (
              <>
                <span>Show Less</span>
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-5 w-5"
                  viewBox="0 0 20 20"
                  fill="currentColor"
                >
                  <path
                    fillRule="evenodd"
                    d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z"
                    clipRule="evenodd"
                  />
                </svg>
              </>
            ) : (
              <>
                <span>Show More ({getFilteredProjects().length - 6})</span>
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-5 w-5"
                  viewBox="0 0 20 20"
                  fill="currentColor"
                >
                  <path
                    fillRule="evenodd"
                    d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"
                    clipRule="evenodd"
                  />
                </svg>
              </>
            )}
          </button>
        </div>
      )}

      {/* Project Detail Modal */}
      {selectedProject && (
        <ProjectDetailModal
          project={selectedProject}
          onClose={() => setSelectedProject(null)}
        />
      )}
    </section>
  );
};

export default ProjectSection;
