import React from "react";

const ProjectCard = ({ project, isVisible, onClick }) => {
  // Function to limit the number of displayed tags
  const renderTags = (tags) => {
    if (!tags || tags.length === 0) return null;
    
    // Show up to 3 tags only
    const visibleTags = tags.slice(0, 3);
    
    return (
      <div className="flex items-center gap-2 overflow-hidden whitespace-nowrap">
        {visibleTags.map((tag, i) => (
          <span
            key={i}
            className="bg-gray-700 text-blue-400 text-xs px-3 py-1 rounded-full truncate"
          >
            {tag}
          </span>
        ))}
        {tags.length > 3 && (
          <span className="text-gray-400 text-xs">+{tags.length - 3}</span>
        )}
      </div>
    );
  };

  return (
    <div
      className={`bg-gray-800 rounded-lg overflow-hidden transition-all duration-300 transform hover:shadow-xl hover:shadow-blue-900/20 hover:scale-105 cursor-pointer w-full h-96 flex flex-col ${
        isVisible ? "opacity-100" : "opacity-0"
      }`}
      onClick={() => onClick(project)}
    >
      <div className="w-full h-48 overflow-hidden">
        <img
          src={`${process.env.PUBLIC_URL}${project.image}`}
          alt={project.title}
          className="w-full h-full object-cover"
        />
      </div>
      <div className="p-6 flex flex-col flex-grow">
        <h3 className="text-xl font-bold mb-2 truncate">{project.title}</h3>
        <p className="text-gray-400 mb-4 line-clamp-2 overflow-hidden text-sm h-10">{project.description}</p>
        <div className="mb-4 h-8">
          {renderTags(project.tags)}
        </div>
        <div className="flex justify-between items-center mt-auto">
          <div className="flex space-x-3">
            {project.url && (
              <a
                href={project.url}
                target="_blank"
                rel="noopener noreferrer"
                className="text-blue-400 hover:text-blue-300 transition"
                onClick={(e) => e.stopPropagation()} // Prevent card click when clicking the link
              >
                <span className="flex items-center">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M12.316 3.051a1 1 0 01.633 1.265l-4 12a1 1 0 11-1.898-.632l4-12a1 1 0 011.265-.633zM5.707 6.293a1 1 0 010 1.414L3.414 10l2.293 2.293a1 1 0 11-1.414 1.414l-3-3a1 1 0 010-1.414l3-3a1 1 0 011.414 0zm8.586 0a1 1 0 011.414 0l3 3a1 1 0 010 1.414l-3 3a1 1 0 11-1.414-1.414L16.586 10l-2.293-2.293a1 1 0 010-1.414z" clipRule="evenodd" />
                  </svg>
                  Code
                </span>
              </a>
            )}
          </div>
          <button 
            className="text-sm text-blue-400 hover:text-blue-300 flex items-center"
            onClick={(e) => {
              e.stopPropagation(); // Prevent double handling
              onClick(project);
            }}
          >
            Details
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 ml-1" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
};

export default ProjectCard;